List<Integer> arr = new ArrayList<>();
List<Integer> linked = new LinkedList<>();

for (int i = 0; i < 100_000; i++) {
    arr.add(i);
    linked.add(i);
}

arr.get(50_000);     // O(1)
linked.get(50_000);  // O(n) — walks 50,000 nodes

// ArrayDeque is almost always the better choice than
// LinkedList when you specifically need a Deque/Queue
Deque<Integer> stack = new ArrayDeque<>();
stack.push(1);
stack.push(2);
stack.pop(); // 2

// Broken: equals() without hashCode() — silent lookup failures
class BadKey {
    final String id;
    BadKey(String id) { this.id = id; }
    @Override public boolean equals(Object o) {
        return o instanceof BadKey bk && bk.id.equals(id);
    }
    // no hashCode() override — uses Object's identity hash
}

Map<BadKey, String> map = new HashMap<>();
map.put(new BadKey("a"), "value");
map.get(new BadKey("a")); // null! different identity hash

// Fixed: a record generates both correctly
record GoodKey(String id) {}
Map<GoodKey, String> fixed = new HashMap<>();
fixed.put(new GoodKey("a"), "value");
fixed.get(new GoodKey("a")); // "value"

// Unmodifiable VIEW — can still change via the original reference
List<String> mutable = new ArrayList<>(List.of("a", "b"));
List<String> view = Collections.unmodifiableList(mutable);
mutable.add("c");
System.out.println(view); // [a, b, c] — view saw the change

// Genuinely immutable — no backing store to mutate
List<String> fixed = List.of("a", "b");
